def redo_pass(log, dpt):
    start = min(dpt.values())          # RedoLSN
    for rec in log.scan_from(start):
        if rec.type not in ("update", "clr"):
            continue
        if rec.page not in dpt:
            continue                   # page was clean at crash
        if rec.lsn < dpt[rec.page]:
            continue                   # flushed before recLSN
        page = buffer_pool.fetch(rec.page)
        if page.page_lsn >= rec.lsn:
            continue                   # update already on disk
        apply(page, rec.redo_data)     # repeat history
        page.page_lsn = rec.lsn        # no log record written

